def _security_upgrade() -> None:
    for table in TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(f'''
            CREATE POLICY tenant_isolation ON {table}
            USING (organisation_id = app_current_org())
            WITH CHECK (organisation_id = app_current_org())
        ''')

    # Signed clinical notes are immutable (rule 4). The only permitted change to a signed
    # version is signed -> amended, made when its amendment is signed.
    op.execute('''
        CREATE FUNCTION clinical_notes_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP = 'DELETE' THEN
                IF OLD.status <> 'draft' THEN
                    RAISE EXCEPTION 'signed clinical notes cannot be deleted';
                END IF;
                RETURN OLD;
            END IF;
            IF OLD.status = 'draft' THEN
                RETURN NEW;
            END IF;
            IF OLD.status = 'signed' AND NEW.status = 'amended'
               AND (NEW.content, NEW.signed_at, NEW.content_sha256, NEW.author_user_id,
                    NEW.note_type, NEW.version_number, NEW.note_group_id, NEW.encounter_id,
                    NEW.patient_id, NEW.amends_note_id, NEW.amendment_reason,
                    NEW.organisation_id)
                   IS NOT DISTINCT FROM
                   (OLD.content, OLD.signed_at, OLD.content_sha256, OLD.author_user_id,
                    OLD.note_type, OLD.version_number, OLD.note_group_id, OLD.encounter_id,
                    OLD.patient_id, OLD.amends_note_id, OLD.amendment_reason,
                    OLD.organisation_id) THEN
                RETURN NEW;
            END IF;
            RAISE EXCEPTION 'signed clinical notes cannot be modified; create an amendment';
        END $$;
        CREATE TRIGGER clinical_notes_immutable BEFORE UPDATE OR DELETE ON clinical_notes
            FOR EACH ROW EXECUTE FUNCTION clinical_notes_guard();

        CREATE FUNCTION prescriptions_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP = 'DELETE' THEN
                RAISE EXCEPTION 'prescriptions cannot be deleted; cancel instead';
            END IF;
            IF OLD.status = 'issued' AND NEW.status = 'cancelled'
               AND (NEW.prescription_number, NEW.patient_id, NEW.encounter_id,
                    NEW.prescriber_user_id, NEW.prescriber_name,
                    NEW.prescriber_registration, NEW.issued_at, NEW.allergy_warning,
                    NEW.organisation_id)
                   IS NOT DISTINCT FROM
                   (OLD.prescription_number, OLD.patient_id, OLD.encounter_id,
                    OLD.prescriber_user_id, OLD.prescriber_name,
                    OLD.prescriber_registration, OLD.issued_at, OLD.allergy_warning,
                    OLD.organisation_id) THEN
                RETURN NEW;
            END IF;
            RAISE EXCEPTION 'issued prescriptions cannot be modified; cancel and reissue';
        END $$;
        CREATE TRIGGER prescriptions_immutable BEFORE UPDATE OR DELETE ON prescriptions
            FOR EACH ROW EXECUTE FUNCTION prescriptions_guard();

        CREATE FUNCTION prescription_items_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN RAISE EXCEPTION 'prescription items cannot be modified'; END $$;
        CREATE TRIGGER prescription_items_immutable
            BEFORE UPDATE OR DELETE OR TRUNCATE ON prescription_items
            FOR EACH STATEMENT EXECUTE FUNCTION prescription_items_guard();
    ''')

    role = get_settings().app_db_role
    op.execute(f'''
        DO $$
        BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{role}') THEN
                GRANT SELECT, INSERT, UPDATE ON encounters, clinical_notes, allergies,
                    allergy_assessments, observations, diagnoses, referrals, prescriptions
                    TO {role};
                GRANT DELETE ON clinical_notes TO {role};  -- drafts only (trigger)
                GRANT SELECT, INSERT ON prescription_items TO {role};
            END IF;
        END $$;
    ''')


